(() => {
    function normalizeMediaText(text) {
        return String(text || '')
            .replace(/\\u002F/g, '/')
            .replace(/\\\//g, '/')
            .replace(/&amp;/g, '&')
            .replace(/\u0026/g, '&')
            .replace(/&quot;/g, '"');
    }
    function absolutizeMediaUrl(url) {
        if (!url) return '';
        url = normalizeMediaText(url).trim().replace(/[),;]+$/g, '');
        try {
            return new URL(url, location.href).href;
        } catch (e) {
            return '';
        }
    }
    function isPreviewMedia(url, context) {
        const text = normalizeMediaText(`${url} ${context || ''}`).toLowerCase();
        return /preview|trailer|sample|teaser|promo|sprite|thumbnail|thumb|cover|poster|still|seek/.test(text)
            || /(?:^|[\/_-])pv(?:[\/_-]|\.)/.test(text)
            || /duration\s*[=:]\s*(?:[0-5]?\d)(?:\D|$)/.test(text);
    }
    function scoreCandidate(candidate) {
        const url = candidate.url || '';
        const context = candidate.context || '';
        const text = normalizeMediaText(`${url} ${context}`).toLowerCase();
        if (!/^https?:\/\//i.test(url)) return -9999;
        let score = 0;
        if (/\.m3u8(?:\?|$)/i.test(url)) score += 160;
        if (/\.mp4(?:\?|$)/i.test(url)) score += 40;
        if (/master|playlist|index|hls|stream|source|video|video_url|m3u8/.test(text)) score += 40;
        if (/1080|720|fhd|hd/.test(text)) score += 10;
        if (isPreviewMedia(url, context)) score -= 600;
        return score;
    }
    function pushCandidate(list, url, context) {
        url = absolutizeMediaUrl(url);
        if (!url || !/\.(?:m3u8|mp4)(?:\?|$)/i.test(url)) return;
        list.push({ url, context: context || '' });
    }
    function collectMedia(text, context, list) {
        const normalized = normalizeMediaText(text);
        const re = /((?:https?:)?\/\/[^"'<>\\\s]+?\.(?:m3u8|mp4)(?:\?[^"'<>\\\s]*)?|\/[^"'<>\\\s]+?\.(?:m3u8|mp4)(?:\?[^"'<>\\\s]*)?)/ig;
        let match;
        while ((match = re.exec(normalized)) !== null) {
            pushCandidate(list, match[1], context);
        }
    }
    function collectAssignedMedia(text, context, list) {
        const normalized = normalizeMediaText(text);
        const re = /([a-zA-Z_$][\w$]*)\s*=\s*['"]([^'"]+\.(?:m3u8|mp4)(?:\?[^'"]*)?)['"]/ig;
        let match;
        while ((match = re.exec(normalized)) !== null) {
            pushCandidate(list, match[2], `${context} ${match[1]}`);
        }
    }
    function decodePackedString(value) {
        return String(value || '').replace(/\\'/g, "'").replace(/\\"/g, '"').replace(/\\\\/g, '\\');
    }
    function collectPackedMissavSources(text, context, list) {
        const re = /eval\(function\(p,a,c,k,e,d\)[\s\S]*?\('((?:\\'|[^'])*)',(\d+),(\d+),'((?:\\'|[^'])*)'\.split\('\|'\),0,\{\}\)\)/g;
        let match;
        while ((match = re.exec(String(text || ''))) !== null) {
            let code = decodePackedString(match[1]);
            const radix = parseInt(match[2], 10);
            const count = parseInt(match[3], 10);
            const words = decodePackedString(match[4]).split('|');
            for (let i = count - 1; i >= 0; i--) {
                if (words[i]) code = code.replace(new RegExp('\\b' + i.toString(radix) + '\\b', 'g'), words[i]);
