        for (let i = resources.length - 1; i >= 0; i--) {
            pushCandidate(list, resources[i].name || '', `resource ${resources[i].initiatorType || ''}`);
        }
        document.querySelectorAll('script').forEach((script, index) => {
            const text = script.textContent || '';
            collectMedia(text, `script ${index}`, list);
            collectAssignedMedia(text, `script ${index}`, list);
            collectPackedMissavSources(text, `script ${index}`, list);
        });
        collectObject(window.__NUXT__, 'window.__NUXT__', list, 0);
        collectObject(window.__NEXT_DATA__, 'window.__NEXT_DATA__', list, 0);
        collectObject(window.player, 'window.player', list, 0);
        collectObject(window.video, 'window.video', list, 0);
        collectObject(window.videojs, 'window.videojs', list, 0);
        collectObject(window.hls, 'window.hls', list, 0);
        try {
            for (let i = 0; i < localStorage.length; i++) {
                const key = localStorage.key(i);
                const value = localStorage.getItem(key);
                collectMedia(value, `localStorage ${key}`, list);
                collectAssignedMedia(value, `localStorage ${key}`, list);
                collectPackedMissavSources(value, `localStorage ${key}`, list);
            }
            for (let i = 0; i < sessionStorage.length; i++) {
                const key = sessionStorage.key(i);
                const value = sessionStorage.getItem(key);
                collectMedia(value, `sessionStorage ${key}`, list);
                collectAssignedMedia(value, `sessionStorage ${key}`, list);
                collectPackedMissavSources(value, `sessionStorage ${key}`, list);
            }
        } catch (e) {}
        const html = document.documentElement.outerHTML;
        collectMedia(html, 'html', list);
        collectAssignedMedia(html, 'html', list);
        collectPackedMissavSources(html, 'html', list);
        const seen = {};
        return list.filter((candidate) => {
            if (!candidate.url || seen[candidate.url]) return false;
            seen[candidate.url] = true;
            return true;
        }).sort((a, b) => scoreCandidate(b) - scoreCandidate(a));
    }
    function triggerPlaybackProbe() {
        let touched = false;
        const selectors = [
            '.plyr__control[data-plyr="play"]',
            'button[data-plyr="play"]',
            '.vjs-big-play-button',
            '.jw-icon-playback',
            '.dplayer-play-icon',
            'button[aria-label*="Play" i]',
            'button[title*="Play" i]',
            'video'
        ];
        selectors.forEach((selector) => {
            document.querySelectorAll(selector).forEach((node) => {
                if (touched) return;
                try {
                    node.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
                    node.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true }));
                    node.click();
                    touched = true;
                } catch (e) {}
            });
        });
        document.querySelectorAll('video').forEach((video) => {
            try {
                video.muted = true;
                video.preload = 'auto';
                if (video.load) video.load();
                const play = video.play && video.play();
                if (play && play.catch) play.catch(() => {});
            } catch (e) {}
        });
        window.dispatchEvent(new Event('focus'));
        document.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, clientX: 10, clientY: 10 }));
        return touched;
    }
    const candidates = collectCandidates();
    const best = candidates.find((candidate) => scoreCandidate(candidate) > 0 && !isPreviewMedia(candidate.url, candidate.context));
    if (best) return best.url;
    window.__missavProbeRound = (window.__missavProbeRound || 0) + 1;
    if (window.__missavProbeRound <= 8) {
        triggerPlaybackProbe();
        return null;
    }
    const fallback = candidates.find((candidate) => scoreCandidate(candidate) > -100 && !isPreviewMedia(candidate.url, candidate.context));
    return fallback ? fallback.url : '未获取到正片地址（页面只暴露预告流，或需要登录/验证）';
})()
